<!DOCTYPE html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}" class="scroll-smooth">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="description" content="{{ __('KI-gestützte Aktienanalyse mit klaren Signalen, Risiko-Kennzahlen und Strategietests.') }}">
    <title>{{ __('AktienKI – Signale früher erkennen') }}</title>
    <link rel="icon" href="{{ asset('brand/generated/bull-icon.png') }}" type="image/png">
    <script>
        (() => {
            const welcomeVersionKey = 'aktienki-welcome-theme-version';
            const welcomeVersion = 'dark-default-v1';
            if (localStorage.getItem(welcomeVersionKey) !== welcomeVersion) {
                localStorage.setItem('aktienki-theme', 'dark');
                localStorage.setItem('aktienki-theme-version', 'light-default-v1');
                localStorage.setItem(welcomeVersionKey, welcomeVersion);
            }
            const dark = localStorage.getItem('aktienki-theme') !== 'light';
            document.documentElement.dataset.theme = dark ? 'dark' : 'light';
            document.documentElement.style.colorScheme = dark ? 'dark' : 'light';
        })();
    </script>
    @vite(['resources/css/app.css', 'resources/js/app.js'])
    <style>
        :root{--bg:#031015;--panel:rgba(7,30,38,.82);--line:rgba(117,242,255,.12);--cyan:#52f1ff;--cyan2:#18cfe3;--text:#f2fdff;--muted:#89a8af;--green:#4df2a8;--red:#ff7b92;--shadow:0 25px 80px rgba(0,0,0,.45)}
        *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--text);background:radial-gradient(circle at 80% 10%,rgba(82,241,255,.10),transparent 24%),radial-gradient(circle at 10% 28%,rgba(24,207,227,.08),transparent 30%),linear-gradient(180deg,#020a0d 0%,#05151b 50%,#030c10 100%);overflow-x:hidden}
        body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.08;background-image:linear-gradient(rgba(82,241,255,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(82,241,255,.08) 1px,transparent 1px);background-size:48px 48px;mask-image:linear-gradient(to bottom,rgba(0,0,0,.9),transparent 85%)}
        a{text-decoration:none;color:inherit}.home-wrap{max-width:1200px;margin:auto;padding:0 24px}.home-header{position:sticky;top:0;z-index:50;background:rgba(2,10,13,.78);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}
        .home-nav{height:76px;display:flex;align-items:center;justify-content:space-between;gap:26px}.home-brand{display:flex;align-items:center;gap:10px;font-size:21px;font-weight:850;letter-spacing:-.02em}.home-brand-mark{width:52px;height:52px;display:block;object-fit:contain;filter:drop-shadow(0 0 8px rgba(82,241,255,.42)) drop-shadow(0 0 22px rgba(24,207,227,.18));transition:transform .2s ease,filter .2s ease}.home-brand:hover .home-brand-mark{transform:translateY(-1px) scale(1.04);filter:drop-shadow(0 0 10px rgba(82,241,255,.62)) drop-shadow(0 0 28px rgba(24,207,227,.28))}.home-brand b{color:var(--cyan)}
        .home-navlinks{display:flex;gap:26px;color:#97b8bf;font-size:14px}.home-navlinks a:hover{color:white}.home-actions{display:flex;gap:10px}.home-btn{padding:11px 16px;border-radius:11px;border:1px solid var(--line);display:inline-flex;align-items:center;justify-content:center;gap:8px;font-size:14px;font-weight:800;transition:.2s}.home-btn:hover{transform:translateY(-1px);border-color:rgba(82,241,255,.35)}.home-btn-primary{color:#001114;background:linear-gradient(135deg,#7df8ff,#27dbe8);border-color:transparent;box-shadow:0 10px 30px rgba(82,241,255,.22)}.home-btn-ghost{background:rgba(255,255,255,.025)}
        .hero{padding:92px 0 66px}.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:60px;align-items:center}.pill{display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(82,241,255,.22);background:rgba(82,241,255,.06);color:#9ff9ff;padding:7px 11px;border-radius:999px;font-size:12px;font-weight:800;letter-spacing:.03em}.pulse{width:7px;height:7px;border-radius:50%;background:var(--cyan);box-shadow:0 0 15px var(--cyan)}
        .hero h1{font-size:clamp(46px,6.3vw,78px);line-height:.98;letter-spacing:-.055em;margin:24px 0 22px}.grad{background:linear-gradient(90deg,#fff 0%,#aafaff 40%,#48ddeb 100%);-webkit-background-clip:text;color:transparent}.lead{font-size:18px;line-height:1.7;color:#9ab4ba;max-width:650px;margin:0 0 31px}.ctas{display:flex;gap:12px;flex-wrap:wrap}.micro{display:flex;gap:20px;flex-wrap:wrap;margin-top:28px;color:#78969d;font-size:12px}.micro span{display:flex;align-items:center;gap:7px}.ok{color:var(--green)}
        .terminal{border:1px solid rgba(82,241,255,.16);background:linear-gradient(180deg,rgba(7,28,35,.96),rgba(3,18,23,.96));border-radius:24px;padding:18px;box-shadow:var(--shadow);position:relative;overflow:hidden;animation:terminalFloat 6s ease-in-out infinite}.terminal:before{content:"";position:absolute;width:250px;height:250px;border-radius:50%;background:rgba(82,241,255,.10);filter:blur(55px);right:-120px;top:-120px;animation:ambientGlow 5s ease-in-out infinite}.term-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.term-title{font-size:13px;font-weight:800}.status{font-size:10px;color:var(--cyan);padding:5px 8px;border-radius:999px;border:1px solid rgba(82,241,255,.17);background:rgba(82,241,255,.05);display:flex;align-items:center;gap:6px}.status:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--cyan);box-shadow:0 0 0 0 rgba(82,241,255,.6);animation:onlinePulse 1.8s ease-out infinite}
        .indices{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.index{padding:11px;border-radius:13px;border:1px solid rgba(255,255,255,.05);background:rgba(255,255,255,.025);opacity:0;animation:metricReveal .55s ease-out forwards}.index:nth-child(2){animation-delay:.12s}.index:nth-child(3){animation-delay:.24s}.index small{font-size:9px;color:#718e95}.index strong{display:block;font-size:13px;margin:5px 0}.up{color:var(--green)}.down{color:var(--red)}
        .ai-card{margin-top:12px;border-radius:17px;padding:16px;background:rgba(3,16,20,.72);border:1px solid rgba(82,241,255,.12);opacity:0;animation:cardReveal .7s .3s ease-out forwards}.stock-head{display:flex;justify-content:space-between;gap:16px}.stock-title{font-size:20px;font-weight:850}.stock-sub{font-size:10px;color:#6f8a91;margin-top:3px}.signal{border-radius:8px;padding:5px 8px;font-size:10px;font-weight:850;color:var(--green);background:rgba(77,242,168,.08);border:1px solid rgba(77,242,168,.18);animation:signalGlow 2.4s ease-in-out infinite}.bigscore{display:flex;align-items:flex-end;gap:11px;margin:16px 0 10px}.bigscore strong{font-size:42px;line-height:.9}.bigscore span{font-size:10px;color:#779097;padding-bottom:4px}.progress{height:6px;background:#0e2930;border-radius:99px;overflow:hidden}.progress span{display:block;width:81%;height:100%;background:linear-gradient(90deg,#18cfe3,#7df8ff);transform-origin:left;animation:progressGrow 1.25s .65s cubic-bezier(.2,.8,.2,1) both}.spark{height:100px;margin-top:12px}.spark svg{width:100%;height:100%;overflow:visible}.spark-area{opacity:0;animation:areaReveal .9s 1.2s ease-out forwards}.spark-line{stroke-dasharray:650;stroke-dashoffset:650;filter:drop-shadow(0 0 4px rgba(82,241,255,.55));animation:chartDraw 2s .8s cubic-bezier(.4,0,.2,1) forwards}.info-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}.info{padding:9px;border-radius:10px;background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.04);opacity:0;animation:metricReveal .5s ease-out forwards}.info:nth-child(1){animation-delay:1.55s}.info:nth-child(2){animation-delay:1.7s}.info:nth-child(3){animation-delay:1.85s}.info small{display:block;font-size:8px;color:#627b81}.info strong{font-size:11px}
        @keyframes terminalFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}@keyframes ambientGlow{0%,100%{opacity:.65;transform:scale(.9)}50%{opacity:1;transform:scale(1.14)}}@keyframes onlinePulse{0%{box-shadow:0 0 0 0 rgba(82,241,255,.65)}70%{box-shadow:0 0 0 7px rgba(82,241,255,0)}100%{box-shadow:0 0 0 0 rgba(82,241,255,0)}}@keyframes metricReveal{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@keyframes cardReveal{from{opacity:0;transform:translateY(12px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes progressGrow{from{transform:scaleX(0)}to{transform:scaleX(1)}}@keyframes chartDraw{to{stroke-dashoffset:0}}@keyframes areaReveal{from{opacity:0}to{opacity:1}}@keyframes signalGlow{0%,100%{box-shadow:0 0 0 rgba(77,242,168,0)}50%{box-shadow:0 0 18px rgba(77,242,168,.18)}}
        .market-demo{padding:30px 0 58px}.market-panel{position:relative;overflow:hidden;border:1px solid rgba(82,241,255,.28);border-radius:25px;background:linear-gradient(135deg,rgba(8,51,61,.88),rgba(3,18,28,.97) 46%,rgba(7,24,37,.96));box-shadow:0 26px 80px rgba(0,0,0,.35),inset 0 0 60px rgba(82,241,255,.025)}.market-panel:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(82,241,255,.06),transparent 35%);pointer-events:none}.market-top{position:relative;z-index:2;display:grid;grid-template-columns:1fr auto;gap:24px;padding:24px 26px 18px;border-bottom:1px solid rgba(82,241,255,.18)}.market-label{font-size:10px;letter-spacing:.18em;font-weight:900;color:var(--cyan)}.market-title{font-size:22px;margin:7px 0 5px}.market-copy{font-size:12px;color:#83a4ad}.donuts{display:flex;gap:15px;align-items:center}.donut{position:relative;width:88px;height:88px;display:grid;place-items:center}.donut svg{position:absolute;inset:0;width:100%;height:100%;transform:rotate(-90deg)}.donut circle{fill:none;stroke-width:7}.donut-track{stroke:rgba(82,241,255,.1)}.donut-value{stroke:var(--cyan);stroke-linecap:round;stroke-dasharray:251.3;stroke-dashoffset:251.3;filter:drop-shadow(0 0 5px rgba(82,241,255,.5));transition:stroke-dashoffset 1.6s cubic-bezier(.2,.8,.2,1)}.donut.active .donut-value{stroke-dashoffset:var(--donut-offset)}.donut-copy{position:relative;text-align:center}.donut-number{display:block;font-size:17px;font-weight:900;color:#d9fdff}.donut-copy small{display:block;margin-top:2px;font-size:7px;letter-spacing:.08em;color:#6f9ca6;text-transform:uppercase}.market-chart{height:330px;position:relative;padding:18px 20px 20px}.chart-grid{position:absolute;inset:18px 20px 32px;background-image:linear-gradient(rgba(82,241,255,.08) 1px,transparent 1px);background-size:100% 25%;border-bottom:1px solid rgba(82,241,255,.13)}.chart-stage{position:relative;width:100%;height:100%;overflow:hidden}.chart-strip{width:200%;height:100%;animation:marketScroll 14s