        main{display:grid;grid-template-columns:minmax(360px,.72fr) minmax(680px,1.28fr);max-width:1500px;margin-inline:auto}main> *{grid-column:1/-1}.hero{grid-column:1;padding-top:92px}.market-demo{grid-column:2;padding-top:92px}.hero-grid{display:block;max-width:560px;margin-left:auto;margin-right:0}.hero-grid>.terminal{display:none}.chart-strip{animation:none}.market-demo>.home-wrap{padding-left:10px}
