document.addEventListener('DOMContentLoaded',()=>{setTimeout(()=>{const ns='http://www.w3.org/2000/svg',closes=[245,238,246,232,248,240,230,235,218,225,205,210,188,195,170,155,130,145,115,135,90,65,110,150,135,165,155,180,165,190,178,205,190,215,198,210,202,220,235,250,230,240,215,225,205],patterns=[-5,4,-3,6,-4,3,-6,5];document.querySelectorAll('.candlestick-layer').forEach(layer=>{layer.replaceChildren();let previous=248;closes.forEach((close,index)=>{const open=index?previous+patterns[index%patterns.length]:250,high=Math.max(18,Math.min(open,close)-(5+(index*7)%14)),low=Math.min(286,Math.max(open,close)+(6+(index*5)%15)),x=12+index*17;const group=document.createElementNS(ns,'g');group.setAttribute('class',close<open?'bull':'bear');group.style.setProperty('--candle-delay',(index*.075)+'s');const wick=document.createElementNS(ns,'line');wick.setAttribute('class','wick');wick.setAttribute('x1',x);wick.setAttribute('x2',x);wick.setAttribute('y1',high);wick.setAttribute('y2',low);const body=document.createElementNS(ns,'rect');body.setAttribute('class','body');body.setAttribute('x',x-3.5);body.setAttribute('y',Math.min(open,close));body.setAttribute('width',7);body.setAttribute('height',Math.max(4,Math.abs(close-open)));group.append(wick,body);layer.append(group);previous=close})})},0)});
document.addEventListener('DOMContentLoaded',()=>{const ns='http://www.w3.org/2000/svg',values=[238,232,236,228,224,230,219,225,215,221,210,198,204,190,181,172,159,143,151,128,104,119,83,111,136,121,148,132,158,146,169,154,177,164,188,179,196,184,205,192,214,201,224,211,235];document.querySelectorAll('.chart-strip').forEach(svg=>{svg.setAttribute('viewBox','0 0 800 300');const indicator=document.createElementNS(ns,'g');indicator.setAttribute('class','indicator-layer');const points=values.map((value,index)=>{const slice=values.slice(Math.max(0,index-6),index+1),mean=slice.reduce((sum,item)=>sum+item,0)/slice.length,variance=slice.reduce((sum,item)=>sum+(item-mean)**2,0)/slice.length,spread=Math.max(13,Math.sqrt(variance)*1.55);return{x:10+index*17,mean,upper:Math.max(20,mean-spread),lower:Math.min(275,mean+spread)}});const path=items=>items.map((point,index)=>(index?'L':'M')+point.x.toFixed(1)+' '+point.y.toFixed(1)).join(' ');const upper=points.map(point=>({x:point.x,y:point.upper})),lower=points.map(point=>({x:point.x,y:point.lower})),mean=points.map(point=>({x:point.x,y:point.mean}));const area=document.createElementNS(ns,'path');area.setAttribute('class','band-area');area.setAttribute('d',path(upper)+' '+path([...lower].reverse()).replace(/^M/,'L')+' Z');indicator.append(area);[upper,lower].forEach(series=>{const line=document.createElementNS(ns,'path');line.setAttribute('class','band-line');line.setAttribute('d',path(series));indicator.append(line)});const average=document.createElementNS(ns,'path');average.setAttribute('class','moving-average');average.setAttribute('d',path(mean));indicator.append(average);[248,266].forEach(y=>{const support=document.createElementNS(ns,'line');support.setAttribute('class','support-line');support.setAttribute('x1','0');support.setAttribute('x2','800');support.setAttribute('y1',y);support.setAttribute('y2',y);indicator.append(support)});const divider=document.createElementNS(ns,'line');divider.setAttribute('class','history-divider');divider.setAttribute('x1','775');divider.setAttribute('x2','775');divider.setAttribute('y1','10');divider.setAttribute('y2','290');indicator.append(divider);svg.append(indicator)})});
