document.addEventListener('DOMContentLoaded',()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const animate=donut=>{if(donut.dataset.animated||!donut.dataset.value)return;donut.dataset.animated='1';donut.classList.add('active');const target=Number(donut.dataset.value),suffix=donut.dataset.suffix||'',output=donut.querySelector('.donut-number');const format=value=>(target%1?value.toFixed(2):Math.round(value))+suffix;if(reduced){output.textContent=format(target);return}const start=performance.now(),duration=1500;const tick=now=>{const progress=Math.min((now-start)/duration,1),eased=1-Math.pow(1-progress,3);output.textContent=format(target*eased);if(progress<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)};const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.querySelectorAll('.donut').forEach((donut,index)=>setTimeout(()=>animate(donut),index*120));observer.unobserve(entry.target)}}),{threshold:.25});document.querySelectorAll('.market-panel').forEach(panel=>observer.observe(panel));const ns='http://www.w3.org/2000/svg',closes=[238,232,236,228,224,230,219,225,215,221,210,198,204,190,181,172,159,143,151,128,104,119,83,111,136,121,148,132,158,146,169,154,177,164,188,179,196,184,205,192,214,201,224,211,235];document.querySelectorAll('.candlestick-layer').forEach(layer=>{let previous=242;closes.forEach((close,index)=>{const open=index===0?244:previous+(index%3-1)*3,high=Math.min(open,close)-(5+(index*7)%13),low=Math.max(open,close)+(6+(index*5)%14),x=10+index*17;const group=document.createElementNS(ns,'g');group.setAttribute('class',close<open?'bull':'bear');const wick=document.createElementNS(ns,'line');wick.setAttribute('class','wick');wick.setAttribute('x1',x);wick.setAttribute('x2',x);wick.setAttribute('y1',high);wick.setAttribute('y2',low);const body=document.createElementNS(ns,'rect');body.setAttribute('class','body');body.setAttribute('x',x-4);body.setAttribute('y',Math.min(open,close));body.setAttribute('width',8);body.setAttribute('height',Math.max(4,Math.abs(close-open)));group.append(wick,body);layer.append(group);previous=close})})});
